-- Slice 2.5 of the forms module: stable field ids on revisions (ADR-0024) and submissions
-- (ADR-0007 V3). Generated by prisma migrate diff, then the hand-written CHECKs, grants and
-- row-level security at the end.
-- AlterTable
ALTER TABLE "forms"."form_revision" ADD COLUMN     "fields" JSONB;

-- CreateTable
CREATE TABLE "forms"."form_submission" (
    "id" UUID NOT NULL,
    "tenant_id" VARCHAR(32) NOT NULL,
    "form_id" UUID NOT NULL,
    "revision_id" UUID NOT NULL,
    "revision_hash" VARCHAR(80) NOT NULL,
    "site_id" UUID NOT NULL,
    "tracking_code_hash" VARCHAR(64) NOT NULL,
    "channel" VARCHAR(16) NOT NULL,
    "submitted_by" UUID,
    "status" VARCHAR(16) NOT NULL,
    "data" BYTEA NOT NULL,
    "submitted_at" TIMESTAMPTZ(3) NOT NULL,
    "erase_after" TIMESTAMPTZ(3),
    "erased_at" TIMESTAMPTZ(3),
    "version" INTEGER NOT NULL,

    CONSTRAINT "form_submission_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "form_submission_tenant_id_form_id_submitted_at_id_idx" ON "forms"."form_submission"("tenant_id", "form_id", "submitted_at", "id");

-- CreateIndex
CREATE INDEX "form_submission_tenant_id_erased_at_erase_after_idx" ON "forms"."form_submission"("tenant_id", "erased_at", "erase_after");

-- CreateIndex
CREATE UNIQUE INDEX "form_submission_tenant_id_id_key" ON "forms"."form_submission"("tenant_id", "id");

-- CreateIndex
CREATE UNIQUE INDEX "form_submission_tenant_id_tracking_code_hash_key" ON "forms"."form_submission"("tenant_id", "tracking_code_hash");

-- AddForeignKey
ALTER TABLE "forms"."form_submission" ADD CONSTRAINT "form_submission_form_fkey" FOREIGN KEY ("tenant_id", "form_id") REFERENCES "forms"."form"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "forms"."form_submission" ADD CONSTRAINT "form_submission_revision_fkey" FOREIGN KEY ("tenant_id", "form_id", "revision_id") REFERENCES "forms"."form_revision"("tenant_id", "form_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- Hand-written: integrity backstops Prisma cannot express; they repeat the module's domain
-- rules. Revisions saved before this migration keep a null field list: the application
-- refuses to publish or accept submissions on them until they are saved again (no backfill,
-- because field ids are UUIDv7 from the IdGenerator, never from SQL).
ALTER TABLE "forms"."form_revision"
  ADD CONSTRAINT "form_revision_fields_check" CHECK (
    "fields" IS NULL OR (jsonb_typeof("fields") = 'array' AND jsonb_array_length("fields") <= 256)
  );

ALTER TABLE "forms"."form_submission"
  ADD CONSTRAINT "form_submission_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "form_submission_revision_hash_check" CHECK ("revision_hash" ~ '^sha256:[0-9a-f]{64}$'),
  ADD CONSTRAINT "form_submission_tracking_code_hash_check" CHECK ("tracking_code_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "form_submission_channel_check" CHECK (
    "channel" IN ('anonymous', 'portal-user', 'staff', 'on-behalf')
  ),
  -- Only an anonymous submission has no submitter.
  ADD CONSTRAINT "form_submission_submitted_by_check" CHECK (
    ("channel" = 'anonymous') = ("submitted_by" IS NULL)
  ),
  ADD CONSTRAINT "form_submission_status_check" CHECK ("status" IN ('received')),
  -- Backs MAX_ANSWERS_BYTES (64 KiB of canonical JSON) plus the cipher's 29-byte header.
  ADD CONSTRAINT "form_submission_data_size_check" CHECK (
    octet_length("data") BETWEEN 29 AND 65565
  ),
  ADD CONSTRAINT "form_submission_erase_after_check" CHECK (
    "erase_after" IS NULL OR "erase_after" > "submitted_at"
  ),
  ADD CONSTRAINT "form_submission_erased_at_check" CHECK (
    "erased_at" IS NULL OR "erased_at" >= "submitted_at"
  ),
  ADD CONSTRAINT "form_submission_version_check" CHECK ("version" >= 1);

-- Grants. A submission's answers and provenance never change (V3); only its status, its
-- version and the erasure mark do. No DELETE: erasure destroys the subject key.
GRANT SELECT, INSERT, UPDATE ("status", "erased_at", "version") ON TABLE "forms"."form_submission" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced, with the reference policy.
ALTER TABLE "forms"."form_submission" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "forms"."form_submission" FORCE ROW LEVEL SECURITY;
CREATE POLICY "form_submission_tenant_isolation" ON "forms"."form_submission"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
